import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}

import { InlineCallout, PageHeader, PricingTable, type PricingCycle, type PricingTier } from '@gntik-ai/blocks';
import { MessageSquare } from '@gntik-ai/icons';
import { Page, Stack, type BreadcrumbItem } from '@gntik-ai/ui';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { upgradeBreadcrumbs, upgradeContent, upgradeTiers } from './data';

export interface UpgradeRequiredProps {
  /** The locked feature, e.g. "Audit log". */
  feature: string;
  /** Lowest plan that includes it. */
  requiredPlan: string;
  currentPlan: string;
  description: string;
  tiers: PricingTier[];
  /** Id of the tier the workspace is on (badge + disabled "Current plan" CTA). */
  currentTierId: string;
  /** Called with the chosen tier and billing cycle. */
  onUpgrade: (tier: PricingTier, cycle: PricingCycle) => void;
  onContactSales: () => void;
  breadcrumbs: BreadcrumbItem[];
  currentHref: string;
  /** ConsoleShell props (app nav, user, workspaces, sidebar footer, topbar…). */
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Plan gate: ConsoleShell + Page with PageHeader, a current-plan callout and a PricingTable. */
export default function UpgradeRequiredPage(props: Partial<UpgradeRequiredProps>) {
  const {
    feature = upgradeContent.feature,
    requiredPlan = upgradeContent.requiredPlan,
    currentPlan = upgradeContent.currentPlan,
    description = upgradeContent.description,
    tiers = upgradeTiers,
    currentTierId = 'starter',
    onUpgrade,
    onContactSales,
    breadcrumbs = upgradeBreadcrumbs,
    currentHref = '/settings',
    shell,
  } = props;
  return (
    <ConsoleShell breadcrumbs={breadcrumbs} currentHref={currentHref} {...shell}>
      <Page
        width="wide"
        header={
          <PageHeader
            breadcrumbs={null}
            title={`${feature} is available on ${requiredPlan}`}
            description={description}
            status=""
            meta={[]}
            tabs={null}
            actions={[{ label: 'Contact sales', icon: MessageSquare, variant: 'secondary', onClick: onContactSales }]}
          />
        }
      >
        <Stack gap={2}>
          <InlineCallout
            tone="info"
            title={`Your workspace is on the ${currentPlan} plan`}
            description={`Upgrade to ${requiredPlan} or above to turn on ${feature.toLowerCase()}. Your data and settings carry over.`}
            actions={[]}
          />
          <PricingTable
            className="px-0 py-8 sm:px-0 sm:py-10"
            eyebrow={null}
            title="Compare plans"
            description="Switch at any time. Upgrades apply immediately and are prorated."
            tiers={tiers}
            currentTierId={currentTierId}
            onSelectTier={(tier, cycle) => {
              if (tier.id !== currentTierId) onUpgrade?.(tier, cycle);
            }}
          />
        </Stack>
      </Page>
    </ConsoleShell>
  );
}

import { samplePricingTiers, type PricingTier } from '@gntik-ai/blocks';
import type { BreadcrumbItem } from '@gntik-ai/ui';

/** Neutral fixtures for the plan gate. */
export const upgradeContent = {
  feature: 'Audit log',
  requiredPlan: 'Team',
  currentPlan: 'Starter',
  description: 'Keep a searchable record of every change in your workspace: who did what, when, and what changed.',
};

export const upgradeBreadcrumbs: BreadcrumbItem[] = [
  { label: 'Acme Industries', href: '/overview' },
  { label: 'Settings', href: '/settings' },
  { label: 'Audit log' },
];

/** The sample tiers; PricingTable marks the current one via `currentTierId`. */
export const upgradeTiers: PricingTier[] = samplePricingTiers;
